-- 0164: cobertura de entrega por produto, em paridade com o Bubble.
--
-- No Bubble, `Produto_ecommerce` tem o campo `*FaixaDeCEP` apontando para UM
-- registro de `FaixaDeCEP`. A migracao original trouxe os 13 intervalos para
-- `faixas_cep` mas perdeu essa relacao, entao nenhum produto do Supabase tinha
-- cobertura declarada.
--
-- Sobre os campos fiscais do Bubble (ICMS, AdValorem, KgAdicional, PesoFinal):
-- eles NAO entram aqui, e nao por esquecimento. Dos 13 registros de
-- `FaixaDeCEP`, os 10 criados em 18/07/2024 (Rio Branco, 69918xxx) tem
-- AdValorem 32 e o resto zerado, e os 3 criados em 2026 — os unicos que os
-- produtos realmente usam — nao trazem nenhum desses campos. Nos registros em
-- uso a faixa delimita regiao e nao calcula nada. O frete continua saindo do
-- `percentual` de `faixas_cep`, sem alteracao.
--
-- A FK aponta para a linha global do intervalo (transportadora_id null), que
-- depois da 0163 e unica por intervalo. `on delete set null` mantem o
-- comportamento seguro: produto sem faixa aparece para todo mundo.

begin;

alter table produtos
  add column if not exists faixa_cep_id uuid
    references faixas_cep(id) on delete set null;

comment on column produtos.faixa_cep_id is
  'Regiao de entrega do produto (paridade Bubble: Produto_ecommerce.*FaixaDeCEP). Null = sem restricao de regiao.';

create index if not exists produtos_faixa_cep_id_idx on produtos (faixa_cep_id)
  where faixa_cep_id is not null;

-- Backfill: 52 associacoes vindas do export do Bubble, casadas por bubble_id.
-- 31 apontam para Manaus (69000000-69099999), 18 para o Acre
-- (69900000-69999999) e 3 para DF/GO (70000000-73699999).
create temp table imp_faixa(bubble_id text primary key, ci bigint, cf bigint) on commit drop;

update produtos p
set faixa_cep_id = f.id
from imp_faixa i
join faixas_cep f
  on f.cep_inicial = i.ci
 and f.cep_final = i.cf
 and f.transportadora_id is null
 and f.loja_id is null
where p.bubble_id = i.bubble_id
  and p.faixa_cep_id is null;

commit;
